(1231624, 154582, 21714, '<td valign="top">Excellent. Totally amazing.</td>', 'Excellent. Totally amazing.', '2005-03-16 09:01:22.000000', NULL, 1),
(1231625, 155056, 32239, '<td valign="top">Nice composition; although, I would like to see a tad more space atop of their heads. I feel the crop is a bit too tight.  Could also use a a bit more sharpness and saturation.</td>', 'Nice composition; although, I would like to see a tad more space atop of their heads. I feel the crop is a bit too tight.  Could also use a a bit more sharpness and saturation.', '2005-03-16 09:02:55.000000', NULL, 1),
