(1232549, 155641, 32378, '<td valign="top">Nicely exposed image, however I think it would have been stronger if taken at the eye level of the children.</td>', 'Nicely exposed image, however I think it would have been stronger if taken at the eye level of the children.', '2005-03-16 15:05:16.000000', NULL, 1),
(1232550, 156573, 29858, '<td valign="top">This is a "Concept Shot" that may actually do well in this challenge.  Good job.  My only critique:  Aren''t they really bitter enemies?!?!  Lol.  Keep up the good work.  8</td>', 'This is a "Concept Shot" that may actually do well in this challenge.  Good job.  My only critique:  Aren''t they really bitter enemies?!?!  Lol.  Keep up the good work.  8', '2005-03-16 15:05:47.000000', NULL, 1),
(1232554, 156586, 29858, '<td valign="top">I really like this shot.  I love the graininess and the harsh light.  I might have used a slight curve adjustment to bring down the blown out white spot on the girls nose and forehead tho.  Anyway: 8</td>', 'I really like this shot.  I love the graininess and the harsh light.  I might have used a slight curve adjustment to bring down the blown out white spot on the girls nose and forehead tho.  Anyway: 8', '2005-03-16 15:07:29.000000', NULL, 1),
(1232555, 156355, 32378, '<td valign="top">Very nice image, I wish the two of them had their back to the camera with the father''s arm on the son''s shoulder.</td>', 'Very nice image, I wish the two of them had their back to the camera with the father''s arm on the son''s shoulder.', '2005-03-16 15:07:57.000000', NULL, 1),
(1232557, 156470, 29858, '<td valign="top">Great concept.  Could have used a better white adjustment, or cures adjustment for the lighting tho. And a fill flash would have brought some hightlights into the girl''s (On the left) eyes.</td>', 'Great concept.  Could have used a better white adjustment, or cures adjustment for the lighting tho. And a fill flash would have brought some hightlights into the girl''s (On the left) eyes.', '2005-03-16 15:09:36.000000', NULL, 1),
