(1241917, 156356, 31606, '<td valign="top">Truly showing best friends.  I like it. 9</td>', 'Truly showing best friends.  I like it. 9', '2005-03-21 20:32:59.000000', NULL, 1),
(1241921, 156268, 31606, '<td valign="top">This would look a lot better if the expression on her face was serious.  Beautiful in B/W.  9</td>', 'This would look a lot better if the expression on her face was serious.  Beautiful in B/W.  9', '2005-03-21 20:34:06.000000', NULL, 1),
