(1244089, 156137, 23680, '<td valign="top">Kinda sad</td>', 'Kinda sad', '2005-03-22 22:28:45.000000', NULL, 1),
(1244090, 154798, 23680, '<td valign="top">Nice portrait, except for the border.  But I don''t see how this depicts "best friends", it may be your best friend which is good, but how is the viewer to know that.  Looks like a nice portrait of a handsome guy.</td>', 'Nice portrait, except for the border.  But I don''t see how this depicts "best friends", it may be your best friend which is good, but how is the viewer to know that.  Looks like a nice portrait of a handsome guy.', '2005-03-22 22:30:01.000000', NULL, 1),
